using Microsoft.EntityFrameworkCore;
namespace Society.Api;

public static class MemberDocumentEndpoints
{
    public static void Map(RouteGroupBuilder t)
    {
        t.MapPost("/members/{id:guid}/photo", async (Guid tenant, Guid id, HttpRequest request, AppDb db, Access a, MembershipService s, IObjectStore store) =>
        {
            var member = await db.Memberships.SingleOrDefaultAsync(x => x.TenantId == tenant && x.Id == id) ?? throw new AccessDeniedException(); if (!await s.IsSelf(member)) await a.Require(tenant, "members.write", member.ChapterId); if (request.ContentLength is null or > 2097152) throw new DomainException("Use a PNG photograph smaller than 2 MB"); using var input = new MemoryStream(); await request.Body.CopyToAsync(input); var png = AssetEndpoints.SanitizePng(input.ToArray()); var document = new MemberDocument { TenantId = tenant, MembershipId = id, Name = "Profile photograph", Kind = "Photo", ContentType = "image/png", Length = png.Length, UploadedBy = a.UserId }; await store.Put(tenant, document.Id, png); db.MemberDocuments.Add(document); var profile = MembershipService.Json(member.Profile); profile["photoUrl"] = $"/api/v1/societies/{tenant}/membership/members/{id}/photo"; member.Profile = profile.ToJsonString(); member.Revision++; s.History(member, a.UserId, "membership.photo.updated", new { document.Id }); await db.SaveChangesAsync(); return Results.NoContent();
        });
        t.MapGet("/members/{id:guid}/photo", async (Guid tenant, Guid id, AppDb db, Access a, MembershipService s, IObjectStore store) =>
        {
            var visible = await s.Directory(tenant); var member = await visible.SingleOrDefaultAsync(x => x.Id == id) ?? throw new AccessDeniedException(); if (!await s.IsSelf(member) && !await a.Can(tenant, "members.read", member.ChapterId) && MembershipService.Json(member.Privacy)["photo"]?.GetValue<bool>() != true) throw new AccessDeniedException(); var document = await db.MemberDocuments.Where(x => x.TenantId == tenant && x.MembershipId == id && x.Kind == "Photo").OrderByDescending(x => x.CreatedAt).FirstOrDefaultAsync() ?? throw new DomainException("No profile photograph has been uploaded"); return Results.File(store.Open(tenant, document.Id), "image/png");
        });
        t.MapGet("/members/{id:guid}/documents", async (Guid tenant, Guid id, AppDb db, Access a, MembershipService s) => { var m = await db.Memberships.SingleOrDefaultAsync(x => x.TenantId == tenant && x.Id == id) ?? throw new AccessDeniedException(); if (!await s.IsSelf(m)) await a.Require(tenant, "members.read", m.ChapterId); return await db.MemberDocuments.Where(x => x.TenantId == tenant && x.MembershipId == id && x.Kind == "Supporting").Select(x => new { x.Id, x.Name, x.Length, x.ContentType, x.CreatedAt }).ToListAsync(); });
        t.MapPost("/members/{id:guid}/documents", async (Guid tenant, Guid id, HttpRequest request, AppDb db, Access a, MembershipService s, IObjectStore store) => { var m = await db.Memberships.SingleOrDefaultAsync(x => x.TenantId == tenant && x.Id == id) ?? throw new AccessDeniedException(); if (!await s.IsSelf(m)) await a.Require(tenant, "members.write", m.ChapterId); if (request.ContentLength is null or > 2097152) throw new DomainException("Documents must be PNG or PDF and smaller than 2 MB"); using var stream = new MemoryStream(); await request.Body.CopyToAsync(stream); var bytes = stream.ToArray(); string contentType; byte[] file; if (bytes.AsSpan().StartsWith(new byte[] { 137, 80, 78, 71 })) { file = AssetEndpoints.SanitizePng(bytes); contentType = "image/png"; } else if (bytes.Length > 20 && System.Text.Encoding.ASCII.GetString(bytes, 0, 5) == "%PDF-" && System.Text.Encoding.ASCII.GetString(bytes, Math.Max(0, bytes.Length - 1024), Math.Min(1024, bytes.Length)).Contains("%%EOF")) { file = bytes; contentType = "application/pdf"; } else throw new DomainException("Upload a valid PNG or PDF document"); var name = request.Query["name"].ToString(); if (string.IsNullOrWhiteSpace(name) || name.Length > 160 || name.Any(char.IsControl)) throw new DomainException("Name this document"); var document = new MemberDocument { TenantId = tenant, MembershipId = id, Name = name, ContentType = contentType, Kind = "Supporting", Length = file.Length, UploadedBy = a.UserId }; await store.Put(tenant, document.Id, file); db.MemberDocuments.Add(document); a.Audit(tenant, "membership.document.uploaded", document.Id); await db.SaveChangesAsync(); return Results.Ok(new { document.Id }); });
        t.MapGet("/members/{id:guid}/documents/{document:guid}", async (Guid tenant, Guid id, Guid document, AppDb db, Access a, MembershipService s, IObjectStore store) => { var m = await db.Memberships.SingleOrDefaultAsync(x => x.TenantId == tenant && x.Id == id) ?? throw new AccessDeniedException(); if (!await s.IsSelf(m)) await a.Require(tenant, "members.read", m.ChapterId); var d = await db.MemberDocuments.SingleOrDefaultAsync(x => x.TenantId == tenant && x.MembershipId == id && x.Id == document) ?? throw new AccessDeniedException(); a.Audit(tenant, "membership.document.downloaded", document); await db.SaveChangesAsync(); return Results.File(store.Open(tenant, document), d.ContentType, d.Name + (d.ContentType == "application/pdf" ? ".pdf" : ".png")); });
    }
}
